{
 "command": "cat tests/test_statements.py; ls tests/golden tests/inputs 2>/dev/null; cat tests/golden/statement_basic.txt; cat tests/inputs/statement_basic.json 2>/dev/null; grep -rn \"MANIFEST\" --include=*.py --include=*.md --include=*.cfg --include=*.toml --include=Makefile . | head",
 "description": "Inspect statement tests and golden files"
}

{
 "command": "cat scripts/regen_goldens.py tests/goldens.py; ls; cat README* CONTRIBUTING* 2>/dev/null | head -50",
 "description": "Read golden regen script and helper"
}

{
 "command": "ls docs; grep -rni \"golden\\|regen\" docs Makefile pyproject.toml | head -20",
 "description": "Search docs for golden file guidance"
}

{
 "command": "python scripts/regen_goldens.py && git diff tests/golden && python -m pytest tests -q 2>&1 | tail -5",
 "description": "Regenerate goldens, show diff, run tests"
}

{
 "command": "git stash -q && python -m pytest tests -q 2>&1 | tail -4; git stash pop -q && git status --short",
 "description": "Check whether other failures predate the change"
}
